Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "usermeta": {
    "deneb": {
      "build": "1.6.2.1",
      "metaVersion": 1,
      "provider": "vegaLite",
      "providerVersion": "5.16.3"
    },
    "interactivity": {
      "tooltip": true,
      "contextMenu": true,
      "selection": true,
      "highlight": true,
      "dataPointLimit": 1000
    },
    "information": {
      "name": "Mapa de calor de calendario",
      "description": "Rejilla de 53 semanas × 7 días por año. El calendario se deriva dentro del spec con timeUnit UTC a partir de UNA columna de fecha. Autor: Cristobal Salcedo Beltrán."
    },
    "dataset": [
      {
        "key": "Date",
        "name": "Date",
        "description": "Fecha a grano DÍA. Una fila por día — el spec no agrega",
        "type": "dateTime",
        "kind": "column"
      },
      {
        "key": "Total Sales",
        "name": "Total Sales",
        "description": "Medida cuya intensidad pinta cada día",
        "type": "numeric",
        "kind": "measure"
      }
    ]
  },
  "config": {
    "background": "transparent",
    "font": "Segoe UI",
    "view": {
      "stroke": "transparent"
    },
    "axis": {
      "grid": false,
      "domain": false,
      "ticks": false,
      "labelColor": "#605E5C",
      "labelFontSize": 11,
      "titleColor": "#252423",
      "titleFontWeight": "normal"
    },
    "text": {
      "font": "Segoe UI"
    }
  },
  "title": {
    "text": "Intensidad de ventas día a día · 2023–2024",
    "subtitle": [
      "Cada celda es un día · color = ventas del día",
      "Contoso Retail · el sábado vende 5× lo del domingo"
    ],
    "anchor": "middle",
    "font": "Segoe UI",
    "fontSize": 21,
    "fontWeight": 600,
    "color": "#1B1A19",
    "subtitleFont": "Segoe UI",
    "subtitleFontSize": 12,
    "subtitleFontWeight": "normal",
    "subtitleColor": "#8A8886",
    "subtitleLineHeight": 17,
    "subtitlePadding": 10,
    "offset": 20
  },
  "description": "Mapa de calor de calendario: x = semana del año, y = día de la semana, una faceta por año. El calendario se deriva con timeUnit UTC desde una sola columna de fecha.",
  "padding": {
    "left": 4,
    "top": 4,
    "bottom": 4,
    "right": 12
  },
  "data": {
    "name": "dataset"
  },
  "spacing": 22,
  "mark": {
    "type": "rect",
    "cornerRadius": 2,
    "stroke": "#FFFFFF",
    "strokeWidth": 1.5
  },
  "encoding": {
    "row": {
      "field": "Date",
      "timeUnit": "utcyear",
      "type": "ordinal",
      "title": null,
      "header": {
        "labelExpr": "utcFormat(datum.value, ''%Y'')",
        "labelAngle": 0,
        "labelAlign": "left",
        "labelAnchor": "start",
        "labelOrient": "top",
        "labelPadding": 2,
        "labelFontSize": 13,
        "labelFontWeight": 600,
        "labelColor": "#3B3A39"
      }
    },
    "x": {
      "field": "Date",
      "timeUnit": "utcweek",
      "type": "ordinal",
      "title": null,
      "axis": {
        "labelExpr": "utcdate(datum.value) <= 7 ? utcFormat(datum.value, ''%b'') : ''''",
        "labelAngle": 0,
        "labelPadding": 6,
        "labelFontSize": 11,
        "orient": "bottom"
      }
    },
    "y": {
      "field": "Date",
      "timeUnit": "utcday",
      "type": "ordinal",
      "title": null,
      "axis": {
        "labelExpr": "[''D'', ''L'', ''M'', ''X'', ''J'', ''V'', ''S''][utcday(datum.value)]",
        "labelPadding": 6,
        "labelFontSize": 11,
        "labelFontWeight": 600,
        "labelColor": "#3B3A39"
      }
    },
    "color": {
      "condition": {
        "test": "datum[''Total Sales''] === 0",
        "value": "#E8E6E3"
      },
      "field": "Total Sales",
      "type": "quantitative",
      "title": null,
      "scale": {
        "type": "linear",
        "range": [
          "#9EF1E0",
          "#72EBC4",
          "#68C98F",
          "#388E84",
          "#116B62",
          "#084F49"
        ]
      },
      "legend": {
        "orient": "right",
        "direction": "vertical",
        "gradientLength": 118,
        "gradientThickness": 8,
        "labelFontSize": 10.5,
        "labelColor": "#605E5C",
        "format": "~s",
        "offset": 10
      }
    },
    "opacity": {
      "condition": [
        {
          "test": "datum.__selected__ === ''off''",
          "value": 0.15
        }
      ],
      "value": 1
    },
    "tooltip": [
      {
        "field": "diaLargo",
        "type": "nominal",
        "title": "Día"
      },
      {
        "field": "Total Sales",
        "type": "quantitative",
        "title": "Ventas",
        "format": ",.0f"
      }
    ]
  },
  "width": 1040,
  "height": 150,
  "transform": [
    {
      "calculate": "[''domingo'',''lunes'',''martes'',''miércoles'',''jueves'',''viernes'',''sábado''][utcday(toDate(datum[''Date'']))] + '', '' + utcdate(toDate(datum[''Date''])) + '' de '' + [''enero'',''febrero'',''marzo'',''abril'',''mayo'',''junio'',''julio'',''agosto'',''septiembre'',''octubre'',''noviembre'',''diciembre''][utcmonth(toDate(datum[''Date'']))] + '' de '' + utcyear(toDate(datum[''Date'']))",
      "as": "diaLargo"
    }
  ]
}'
